pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // 1. Restrict to admissible domain: depositAmount in [1, type(uint112).max] to avoid overflow later, withdrawAmount up to depositAmount
        vm.assume(depositAmount >= 1 && depositAmount <= type(uint112).max);
        vm.assume(withdrawAmount <= depositAmount && withdrawAmount >= 1);

        // 2. Setup: give owner some ether, deposit, then withdraw part via withdraw(...) so balance > 0 before withdrawAll
        address owner = c.owner();
        vm.deal(owner, depositAmount);
        vm.startPrank(owner);
        (bool ok, ) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");
        c.withdraw(withdrawAmount);
        vm.stopPrank();

        uint256 balanceBefore = address(c).balance;
        // balanceBefore = depositAmount - withdrawAmount; strictly > 0 because withdrawAmount < depositAmount

        // 3. Drive through withdrawAll
        vm.prank(owner);
        c.withdrawAll();

        uint256 balanceAfter = address(c).balance;
        // Reference C: balanceAfter == 0.
        // Buggy M (empty body): balanceAfter == balanceBefore > 0.
        assertTrue(balanceAfter == 0);
    }
}

