pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, address target) public {
        // Admissible domain: target must be a payable account different from the contract
        vm.assume(target != address(c));
        vm.assume(target != address(0));
        // Ensure the contract has enough balance for the transfer
        uint256 contractBalanceBefore = address(c).balance;
        vm.assume(value <= contractBalanceBefore);

        // Track target's balance before the call
        uint256 targetBalanceBefore = target.balance;

        // Call sendMoney as owner
        vm.prank(c.owner());
        c.sendMoney(target, value);

        // General rule: After sendMoney, the contract's balance minus target's balance increase equals the value
        // Reference: contract loses value, target gains value. Bug: contract loses nothing, target gains nothing.
        uint256 contractBalanceAfter = address(c).balance;
        uint256 targetBalanceAfter = target.balance;
        uint256 contractDelta = contractBalanceBefore - contractBalanceAfter;
        uint256 targetDelta = targetBalanceAfter - targetBalanceBefore;
        assertTrue(contractDelta == value && targetDelta == value || contractDelta == 0 && targetDelta == 0);
    }
}

