contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        vm.assume(_target != address(0) && _target != address(c) && _target != address(this));
        vm.deal(address(c), _value);
        uint256 beforeBal = _target.balance;
        vm.prank(c.owner());
        (bool ok,) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", _target, _value));
        if (ok) {
            assertTrue(_target.balance == beforeBal + _value);
        } else {
            assertTrue(_target.balance == beforeBal);
        }
    }
}

