pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // 1. Restrict to admissible domain: target must be a non-zero address that can receive Ether, and value must be non-zero and funded
        vm.assume(target != address(0) && target != address(c));
        vm.assume(value > 0);
        // 2. Setup: fund the contract owner (default sender) and the contract itself
        address owner = address(this);
        vm.deal(owner, value);
        vm.prank(owner);
        (bool funded,) = address(c).call{value: value}("");
        require(funded, "funding failed");
        uint256 balanceBefore = address(c).balance;
        // 3. Drive sendMoney as owner
        vm.prank(owner);
        bool success;
        try c.sendMoney(target, value) { success = true; } catch { success = false; }
        // 4. Assertion: if the call succeeded, the contract's balance must have decreased by exactly value
        if (success) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore - value, "balance must decrease by sent value");
        }
    }
}

